import std.io;

fn is_space(c: int) -> [] bool {
    return c == 32 || c == 10 || c == 9 || c == 13;
}

fn count_words[&i](io: &!i Io) -> [io_read] int {
    var words = 0;
    var in_word = false;
    var c = getchar(io);
    while c >= 0 {
        if is_space(c) {
            in_word = false;
        } else {
            if !in_word {
                words = words + 1;
            }
            in_word = true;
        }
        c = getchar(io);
    }
    return words;
}

fn print_nat[&o](io: &!o Io, n: int) -> [io_write] int {
    if n >= 10 {
        print_nat(io, n / 10);
    }
    putchar(io, '0' + n % 10);
    return 0;
}

fn main(world: World) -> [] int {
    let Split { io, ffi, fs, heap, args } = split(world);
    release(ffi);
    release(fs);
    release(heap);
    release(args);
    var n = 0;
    borrow mut io as &!i in {
        n = count_words(i);
    }
    borrow mut io as &!o in {
        print_nat(o, n);
        putchar(o, 10);
    }
    release(io);
    return 0;
}

